/* eslint-disable @typescript-eslint/no-unused-vars */
"use client";

import React, { useState, useEffect } from "react";
import { UserAvatar } from "@/components/HeaderBalance";
import { PiHandDepositFill, PiHandWithdrawFill } from "react-icons/pi";
import { FiRefreshCw, FiDownload } from "react-icons/fi";
import { FaCopy, FaCreditCard, FaGift, FaChartLine, FaFileInvoiceDollar, FaCircleUser } from "react-icons/fa6";
import { IoLogOut } from "react-icons/io5";
import { LuNotebookText } from "react-icons/lu";
import { MdSecurity, MdOutlineSupportAgent } from "react-icons/md";
import { TiUserAdd } from "react-icons/ti";
import { GiFishMonster } from "react-icons/gi";
import Link from "next/link";
import { useFetchWalletQuery } from "@/lib/features/walletApiSlice";
import { getCurrencySymbol } from "@/lib/utils";
import useCurrentUser from "@/hook/useCurrentUser";
import { Skeleton } from "@/components/ui/skeleton";
import LogOutModal from "@/components/logout-modal";

const App: React.FC = () => {
  const [copied, setCopied] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [showToast, setShowToast] = useState(false);
  const [lastUpdateTime, setLastUpdateTime] = useState(new Date());

  const user: any = useCurrentUser();

  const {
    data,
    isLoading: walletLoading,
    refetch,
    isFetching: walletRetching,
  } = useFetchWalletQuery();

  const balance = data?.payload
    ? Number(data.payload.balance)
    : 0;

  const handleCopyPlayerId = () => {
    if (!user?.playerId) return;

    navigator.clipboard.writeText(String(user.playerId));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleRefreshBalance = async () => {
    if (isRefreshing) return;

    setIsRefreshing(true);

    try {
      await refetch();
      setLastUpdateTime(new Date());
      setShowToast(true);
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    if (!showToast) return;

    const timer = setTimeout(() => {
      setShowToast(false);
    }, 3000);

    return () => clearTimeout(timer);
  }, [showToast]);

  const menuItems = [
    {
      title: "Reward",
      href: "/rewardCenter",
      icon: FaGift,
    },
    {
      title: "Profit/Loss",
      href: "/profitandloss",
      icon: FaChartLine,
    },
    {
      title: "Deposit Record",
      href: "/history?type=deposit",
      icon: FaFileInvoiceDollar,
    },
    {
      title: "Withdraw Record",
      href: "/history?type=withdraw",
      icon: LuNotebookText,
    },
    {
      title: "My Account",
      href: "/my-account",
      icon: FaCircleUser,
    },
    {
      title: "Security Center",
      href: "/security",
      icon: MdSecurity,
    },
    {
      title: "Invite Friend",
      href: "/invite-friends",
      icon: TiUserAdd,
    },
    {
      title: "Download App",
      href: "#",
      icon: FiDownload,
    },
    {
      title: "Customer Center",
      href: "/support",
      icon: MdOutlineSupportAgent,
    },
  ];

  return (
    <div className="min-h-screen w-full bg-[#020018] px-2 py-4 pb-20 text-[#e8c8ff] md:flex md:flex-col md:items-center md:px-4">

      <div className="w-full md:max-w-4xl">

        {/* Toast Notification */}
        <div
          className={`fixed left-1/2 top-4 z-50 -translate-x-1/2 rounded-xl border border-[#a855f7] bg-gradient-to-r from-[#351052] to-[#70269c] px-4 py-3 text-white shadow-[0_0_20px_rgba(168,85,247,0.3)] transition-opacity duration-300 ${
            showToast
              ? "opacity-100"
              : "pointer-events-none opacity-0"
          }`}
        >
          <div className="text-sm font-semibold">
            Balance updated successfully
          </div>
          <div className="mt-1 text-xs text-[#e8c8ff]" suppressHydrationWarning>
            {lastUpdateTime.toLocaleTimeString()}
          </div>
        </div>

        {/* Profile Section */}
        <div className="relative overflow-hidden rounded-[24px] border border-[#70269c] bg-gradient-to-br from-[#26083f] via-[#150329] to-[#080014] p-4 shadow-[0_5px_25px_rgba(112,38,156,0.2)] md:mt-4 md:p-6">

          <div className="pointer-events-none absolute -right-16 -top-20 h-48 w-48 rounded-full bg-[#a21caf]/15 blur-3xl" />

          <div className="relative flex items-center justify-between gap-3">

            <div className="flex min-w-0 items-center">
              <div className="shrink-0 rounded-full border-2 border-[#d946ef] p-1 shadow-[0_0_15px_rgba(217,70,239,0.3)]">
                <UserAvatar imageUrl="https://images.51939393.com//TCG_PROD_IMAGES/B2C/01_PROFILE/PROFILE/0.png" />
              </div>

              <div className="ml-3 min-w-0">
                <h2 className="truncate text-lg font-bold text-white md:text-xl">
                  {user?.name}
                </h2>

                <div className="mt-1 flex items-center gap-2">
                  <span className="truncate text-xs text-[#d9b5f5] md:text-sm">
                    Player ID: {user?.playerId}
                  </span>

                  <button
                    type="button"
                    onClick={handleCopyPlayerId}
                    className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg border border-[#70269c] bg-[#351052] text-[#e8c8ff] transition hover:bg-[#70269c]"
                    title="Copy Player ID"
                  >
                    <FaCopy size={12} />
                  </button>

                  {copied && (
                    <span className="text-xs font-semibold text-[#e879f9]">
                      Copied!
                    </span>
                  )}
                </div>
              </div>
            </div>

            <LogOutModal>
              <button
                type="button"
                aria-label="Logout"
                className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-[#70269c] bg-[#351052] text-white transition hover:border-[#e879f9] hover:bg-[#70269c]"
              >
                <IoLogOut className="h-5 w-5 md:h-6 md:w-6" />
              </button>
            </LogOutModal>
          </div>

          {/* Balance */}
          <div className="relative mt-5 rounded-2xl border border-[#62218b] bg-[#080014]/70 p-4">

            <div className="flex items-center justify-between gap-3">
              <div>
                <span className="text-xs font-semibold uppercase tracking-wider text-[#c084fc] md:text-sm">
                  Available Balance
                </span>

                <div className="mt-1 flex items-center gap-2">
                  <span
                    className="text-2xl font-extrabold text-[#e879f9] md:text-3xl"
                    style={{
                      animation: isRefreshing
                        ? "none"
                        : "balancePulse 0.5s ease-out",
                    }}
                  >
                    {(walletLoading || walletRetching) && (
                      <Skeleton className="h-[30px] w-[100px] rounded-md bg-[#351052]" />
                    )}

                    {!walletLoading && !walletRetching && data && (
                      <>
                        {getCurrencySymbol("BDT")}
                        {balance.toFixed(2)}
                      </>
                    )}

                    {!walletLoading && !walletRetching && !data && (
                      <>
                        {getCurrencySymbol("BDT")}0.00
                      </>
                    )}
                  </span>

                  <style>
                    {`
                      @keyframes balancePulse {
                        0% { transform: scale(1); }
                        50% { transform: scale(1.05); }
                        100% { transform: scale(1); }
                      }
                    `}
                  </style>

                  <button
                    type="button"
                    onClick={handleRefreshBalance}
                    disabled={isRefreshing || walletRetching}
                    aria-label="Refresh balance"
                    className="flex h-8 w-8 items-center justify-center rounded-lg border border-[#70269c] bg-[#351052] text-[#e879f9] transition hover:bg-[#70269c] disabled:opacity-50"
                  >
                    <FiRefreshCw
                      className={`h-4 w-4 ${
                        isRefreshing || walletRetching
                          ? "animate-spin"
                          : ""
                      }`}
                    />
                  </button>
                </div>
              </div>

              <div className="hidden rounded-xl border border-[#70269c] bg-[#351052] p-3 sm:block">
                <FaCreditCard className="text-2xl text-[#e879f9]" />
              </div>
            </div>
          </div>
        </div>

        {/* Main Action Buttons */}
        <div className="grid grid-cols-3 gap-2 px-1 py-4 md:gap-4 md:px-0 md:py-5">

          <Link href="/deposit" className="min-w-0">
            <div className="flex h-[65px] items-center justify-center gap-2 rounded-2xl border border-[#d946ef] bg-gradient-to-b from-[#c026d3] to-[#70269c] text-white shadow-[0_4px_0_#351052,0_5px_12px_rgba(192,38,211,0.2)] transition hover:brightness-125 active:translate-y-1 active:shadow-none md:h-[75px]">
              <PiHandDepositFill className="h-6 w-6 shrink-0 md:h-7 md:w-7" />
              <span className="text-sm font-bold md:text-lg">
                Deposit
              </span>
            </div>
          </Link>

          <Link href="/withdraw" className="min-w-0">
            <div className="flex h-[65px] items-center justify-center gap-2 rounded-2xl border border-[#a855f7] bg-gradient-to-b from-[#70269c] to-[#351052] text-white shadow-[0_4px_0_#160025,0_5px_12px_rgba(112,38,156,0.2)] transition hover:brightness-125 active:translate-y-1 active:shadow-none md:h-[75px]">
              <PiHandWithdrawFill className="h-6 w-6 shrink-0 md:h-7 md:w-7" />
              <span className="text-sm font-bold md:text-lg">
                Withdraw
              </span>
            </div>
          </Link>

          <Link href="/my-cards" className="min-w-0">
            <div className="flex h-[65px] items-center justify-center gap-2 rounded-2xl border border-[#70269c] bg-gradient-to-b from-[#351052] to-[#150329] text-white shadow-[0_4px_0_#080014] transition hover:border-[#d946ef] hover:brightness-125 active:translate-y-1 active:shadow-none md:h-[75px]">
              <FaCreditCard className="h-5 w-5 shrink-0 md:h-6 md:w-6" />
              <span className="text-sm font-bold md:text-lg">
                My Card
              </span>
            </div>
          </Link>
        </div>

        {/* Member Menu */}
        <div className="rounded-2xl border border-[#351052] bg-gradient-to-b from-[#100525] to-[#080014] px-3 py-5 shadow-[0_4px_20px_rgba(112,38,156,0.1)] md:px-5 md:py-6">

          <div className="mb-5 flex items-center justify-between">
            <h3 className="text-lg font-bold text-white md:text-xl">
              Member Menu
            </h3>

            <span className="rounded-full border border-[#70269c] bg-[#351052] px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-[#e879f9]">
              Account
            </span>
          </div>

          <div className="grid grid-cols-4 gap-x-2 gap-y-6 md:gap-x-4 md:gap-y-8">

            {menuItems.map((item) => {
              const Icon = item.icon;

              return (
                <Link
                  key={item.title}
                  href={item.href}
                  className="group flex min-w-0 flex-col items-center text-center"
                >
                  <div className="flex h-12 w-12 items-center justify-center rounded-2xl border border-[#62218b] bg-gradient-to-b from-[#351052] to-[#150329] shadow-[0_3px_0_#080014] transition duration-200 group-hover:-translate-y-1 group-hover:border-[#d946ef] group-hover:shadow-[0_0_15px_rgba(217,70,239,0.25)] md:h-14 md:w-14">
                    <Icon className="h-5 w-5 text-[#e8c8ff] transition group-hover:text-[#f0abfc] md:h-6 md:w-6" />
                  </div>

                  <span className="mt-2 text-[11px] font-medium leading-tight text-[#d9b5f5] transition group-hover:text-white md:text-sm">
                    {item.title}
                  </span>
                </Link>
              );
            })}

          </div>
        </div>

      </div>
    </div>
  );
};

export default App;

"use client";
import { UserAvatar } from "@/components/HeaderBalance";
import React, { useEffect, useState } from "react";
import { FaCopy } from "react-icons/fa";
import { FiRefreshCw } from "react-icons/fi";
import { IoLogOut } from "react-icons/io5";
import { FaArrowLeftLong } from "react-icons/fa6";
import { useRouter } from "next/navigation";
import useCurrentUser from "@/hook/useCurrentUser";
import { useFetchWalletQuery } from "@/lib/features/walletApiSlice";
import { getCurrencySymbol } from "@/lib/utils";

const RewardHeader = () => {
  const [copied, setCopied] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [showToast, setShowToast] = useState(false);
  const [lastUpdateTime, setLastUpdateTime] = useState(new Date());

  const { data, refetch, error } = useFetchWalletQuery();

  const user : any = useCurrentUser();

  const balance = data?.payload ? Number(data.payload.balance) : 0;

  const handleCopyPlayerId = () => {
    navigator.clipboard.writeText(user?.playerId || "");
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleRefreshBalance = async () => {
    if (isRefreshing) return;

    setIsRefreshing(true);

    // Simulate API call
    await new Promise((resolve) => setTimeout(resolve, 1000));

    refetch();

    setLastUpdateTime(new Date());
    setShowToast(true);
    setIsRefreshing(false);
  };

  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => {
        setShowToast(false);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  const router = useRouter();

  const handleBack = () => {
    router.back();
  };

  return (
    <div className="relative reward-header-bg rounded-b-full  p-2 h-[240px] flex items-center">
      {/* Toast Notification */}
      <div
        className={`fixed top-4 left-1/2 transform -translate-x-1/2 bg-green-500 text-white px-4 py-2 rounded-lg shadow-lg transition-opacity duration-300 z-50 ${
          showToast ? "opacity-100" : "opacity-0 pointer-events-none"
        }`}
      >
        <div className="text-sm font-medium">Balance updated successfully</div>
        <div className="text-xs mt-1" suppressHydrationWarning>
          {lastUpdateTime.toLocaleTimeString()}
        </div>
      </div>

      <h2 className="text-[60px]   font-bold absolute left-1/2 -translate-x-1/2 top-5  text-transparent bg-[linear-gradient(#fff,#0000)] bg-clip-text">
        Reward
      </h2>

      <button
        className="cursor-pointer absolute top-4 left-5"
        onClick={handleBack}
      >
        <FaArrowLeftLong className="w-5 h-5 text-white" />
      </button>

      <div className=" flex items-center justify-between mb-4">
        <div className=" flex items-center">
          <div className="absolute -bottom-[25%] -translate-y-1/2 left-14">
            <div
              className={`overflow-x-hidden overflow-y-hidden p-0.5 mr-2 border border-t border-r border-b border-l border-solid bg-[linear-gradient(rgb(255,230,0),rgb(255,184,0))] border-orange-200 border-opacity-50   shadow-[hsl(51.23595505617977, 100%, 82.54901960784314%)_0px_1.9584px_0px_1.7px_inset,rgb(182,65,0)_0px_1.9584px_0px_0px]  w-[120px] h-[120px] md:w-[150px] md:h-[150px] rounded-full `}
            >
              <div className="flex overflow-x-hidden overflow-y-hidden relative justify-center items-center rounded-full size-full">
                <div className="overflow-x-hidden overflow-y-hidden rounded-full size-full">
                  <img
                    alt="User avatar"
                    src="https://images.51939393.com//TCG_PROD_IMAGES/B2C/01_PROFILE/PROFILE/0.png"
                    className="overflow-x-clip overflow-y-clip size-full  object-cover"
                    onError={(e) => {
                      const target = e.target as HTMLImageElement;
                      target.src = "https://images.51939393.com//TCG_PROD_IMAGES/B2C/01_PROFILE/PROFILE/0.png";
                    }}
                  />
                </div>
              </div>
            </div>
          </div>
          <div className="ml-3 absolute left-[40%] -bottom-4 -translate-y-1/2">
            <h2 className="font-bold text-xl text-white">{user?.name}</h2>
            <div className="flex items-center mt-1">
              <span className="text-sm text-gray-200">
                Player ID: {user?.playerId}
              </span>
              <button
                onClick={handleCopyPlayerId}
                className="ml-2 text-xs bg-gray-200 hover:bg-gray-400 p-1 rounded cursor-pointer"
              >
                <FaCopy className="text-[#B0235F]" />
              </button>
            </div>

            <div className="flex items-center justify-between  ">
              <div>
                <div className="flex items-center">
                  <span
                    className="text-xl font-bold tracking-tighter text-white mt-2 transition-all duration-300 transform"
                    style={{
                      animation: isRefreshing
                        ? "none"
                        : "balancePulse 0.5s ease-out",
                    }}
                  >
                    {getCurrencySymbol(data?.payload?.currency || "BDT")}
                    {balance.toFixed(2)}
                  </span>
                  <style>
                    {`
                @keyframes balancePulse {
                  0% { transform: scale(1); }
                  50% { transform: scale(1.05); }
                  100% { transform: scale(1); }
                }
              `}
                  </style>
                  <button
                    onClick={handleRefreshBalance}
                    className="ml-2 text-xs bg-gray-200 hover:bg-gray-400 p-1.5 rounded cursor-pointer relative"
                    disabled={isRefreshing}
                  >
                    <FiRefreshCw className="text-[#B0235F]" />
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RewardHeader;

"use client";
import { useEffect } from "react";
import { useFetchGamesListMutation } from "@/lib/features/gamesApiSlice";
import { useGames } from "@/lib/store.zustond";

export default function GamesLoader(){
  const [fetchGamesList,{data,isLoading,error}]=useFetchGamesListMutation();
  const {setLoading,setGames}=useGames(s=>s);
  useEffect(()=>{fetchGamesList({game_type:"all"})},[fetchGamesList]);
  useEffect(()=>{if(data){setGames(data.gamesList as any);setLoading(false)}else if(error){setGames({} as any);setLoading(false)}},[data,error,setGames,setLoading]);
  return null;
}

"use client";

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Users,
  DollarSign,
  TrendingUp,
  Eye,
  Copy,
  Award
} from 'lucide-react';

interface AffiliateData {
  isAffiliate: boolean;
  affiliate?: {
    id: string;
    affiliateCode: string;
    isActive: boolean;
    tier: string;
    totalEarnings: number;
    pendingEarnings: number;
    totalReferrals: number;
    activeReferrals: number;
    commissionRate: number;
    createdAt: string;
  };
  message?: string;
}

interface AnalyticsData {
  overview: {
    totalClicks: number;
    totalReferrals: number;
    activeReferrals: number;
    conversionRate: number;
    totalEarnings: number;
    pendingEarnings: number;
    thisMonthEarnings: number;
  };
  chartData: {
    clicks: Array<{ date: string; clicks: number }>;
    earnings: Array<{ date: string; amount: number }>;
  };
  topReferrals: Array<{
    id: string;
    name: string;
    phone: string;
    totalDeposits: number;
    totalCommissions: number;
    joinDate: string;
    status: string;
  }>;
}

const AffiliatePage = () => {
  const [affiliateData, setAffiliateData] = useState<AffiliateData | null>(null);
  const [analyticsData, setAnalyticsData] = useState<AnalyticsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [registering, setRegistering] = useState(false);

  useEffect(() => {
    fetchAffiliateData();
    fetchAnalyticsData();
  }, []);

  const fetchAffiliateData = async () => {
    try {
      const response = await fetch('/api/affiliate');

      // Check if response is ok before parsing JSON
      if (!response.ok) {
        const errorText = await response.text();
        console.error('Fetch affiliate data failed:', errorText);
        throw new Error(`Fetch affiliate data failed with status ${response.status}: ${errorText}`);
      }

      const text = await response.text();
      if (!text) {
        throw new Error('Empty response from server');
      }

      const data = JSON.parse(text);
      setAffiliateData(data);
    } catch (error) {
      console.error('Error fetching affiliate data:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchAnalyticsData = async () => {
    try {
      const response = await fetch('/api/affiliate/analytics');

      // Check if response is ok before parsing JSON
      if (!response.ok) {
        const errorText = await response.text();
        console.error('Fetch analytics data failed:', errorText);
        throw new Error(`Fetch analytics data failed with status ${response.status}: ${errorText}`);
      }

      const text = await response.text();
      if (!text) {
        throw new Error('Empty response from server');
      }

      const data = JSON.parse(text);
      if (data && data.success) {
        setAnalyticsData(data.data);
      }
    } catch (error) {
      console.error('Error fetching analytics data:', error);
    }
  };

  const handleRegisterAsAffiliate = async () => {
    setRegistering(true);
    try {
      const response = await fetch('/api/affiliate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({}),
      });

      // Check if response is ok before parsing JSON
      if (!response.ok) {
        const errorText = await response.text();
        console.error('Register affiliate failed:', errorText);
        throw new Error(`Register affiliate failed with status ${response.status}: ${errorText}`);
      }

      const text = await response.text();
      if (!text) {
        throw new Error('Empty response from server');
      }

      const data = JSON.parse(text);

      if (data && data.success) {
        await fetchAffiliateData();
      } else {
        alert(data.message || 'Failed to register as affiliate');
      }
    } catch (error) {
      console.error('Error registering as affiliate:', error);
      alert('Failed to register as affiliate');
    } finally {
      setRegistering(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    alert('Copied to clipboard!');
  };

  const getTierColor = (tier: string) => {
    switch (tier) {
      case 'BRONZE': return 'bg-amber-600';
      case 'SILVER': return 'bg-gray-400';
      case 'GOLD': return 'bg-yellow-500';
      case 'PLATINUM': return 'bg-purple-600';
      case 'DIAMOND': return 'bg-blue-600';
      default: return 'bg-gray-500';
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black p-6">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center justify-center h-64">
            <div className="text-white text-xl">Loading affiliate dashboard...</div>
          </div>
        </div>
      </div>
    );
  }

  if (!affiliateData?.isAffiliate) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black p-6">
        <div className="max-w-4xl mx-auto">
          <Card className="bg-gray-800 border-gray-700">
            <CardHeader className="text-center">
              <CardTitle className="text-3xl font-bold text-white mb-4">
                Join Our Affiliate Program
              </CardTitle>
              <p className="text-gray-300 text-lg">
                Earn commissions by referring new players to our platform
              </p>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="grid md:grid-cols-3 gap-6">
                <div className="text-center p-6 bg-gray-700 rounded-lg">
