            ) : gamesList.length > 0 ? (
              gamesList.map((game, i) => (
                <GameCardWithProvider game={game} key={i} />
              ))
            ) : null}
          </div>

          {/* No Result */}
          {!loading && gamesList.length === 0 && (
            <span className="block text-center text-lg font-semibold text-[#23FFC8] mt-5">
              Not Found
            </span>
          )}
        </main>
      </div>
