/**
 * Generate a unique invoice number
 * @returns string
 */
export const generateInvoiceNumber = (): string => {
  const timestamp = Date.now().toString();
  const random = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
  return `INV_${timestamp}_${random}`;
};

